function defaultPlanFor(topic, category) {
  const focus = topic.focus || topic.title.toLowerCase();
  return [
    ["Сформулируйте практическую цель", `Сведите тему к одному действию: ${focus}. Так занятие перестает быть абстрактным и превращается в проверяемую тренировку.`],
    ["Возьмите короткий материал", `Выберите один диалог, текст, аудио или вопрос, где эта тема встречается естественно. Маленький фрагмент легче разобрать глубоко, чем большой материал поверхностно.`],
    ["Сделайте активный ответ", "Не ограничивайтесь чтением объяснения. Произнесите ответ вслух, напишите две свои фразы или перескажите смысл без подсказки."],
    ["Вернитесь к ошибке позже", "Через день или два повторите не всю тему, а именно то место, где возникла ошибка. Так знание постепенно становится навыком."],
  ];
}

function defaultMistakesFor(topic) {
  return [
    ["Искать один волшебный прием", `В теме «${topic.title}» обычно работает не один трюк, а связка: понятное объяснение, активная попытка, ошибка и повторение.`],
    ["Путать понимание с умением", "Если фраза кажется понятной, это еще не значит, что вы сможете быстро использовать ее в речи. Навык появляется только после самостоятельного ответа."],
    ["Заниматься без обратной связи", "Без проверки легко закрепить неточную форму, странное произношение или неестественный порядок слов. Ошибка должна быть видимой."],
  ];
}

function makeExtendedArticle(topic) {
  const category = extendedCategoryCopy[topic.categoryId];
  if (!category) {
    throw new Error(`Unknown knowledge category: ${topic.categoryId}`);
  }
  const faq = [...category.faq, ...(topic.faq || [])].slice(0, 5);
  return {
    number: topic.number,
    slug: topic.slug,
    path: `/knowledge/${topic.slug}.html`,
    title: topic.title,
    categoryId: topic.categoryId,
    category: category.label,
    cluster: category.label,
    readingTime: topic.readingTime || 8,
    updated: knowledgeUpdatedLabel,
    updatedIso: knowledgeUpdatedIso,
    tags: topic.tags || category.tags,
    keywords: [...category.keywords, ...(topic.keywords || [])],
    excerpt: topic.excerpt,
    directAnswer: topic.answer,
    why: [
      topic.why,
      category.principle,
      topic.depth || "Главный ориентир простой: тема должна начать работать в реальной фразе. Если после занятия вы можете объяснить мысль своими словами, услышать знакомую конструкцию и применить ее в коротком ответе, значит материал перестал быть теорией.",
    ],
    plan: topic.plan || defaultPlanFor(topic, category),
    mistakes: topic.mistakes || defaultMistakesFor(topic),
    neriva: topic.neriva || category.neriva,
    faq,
  };
}

