function validateKnowledgeArticles() {
  const categoryIds = new Set(knowledgeCategories.map((category) => category.id));
  const seenSlugs = new Set();
  const seenPaths = new Set();

  if (knowledgeArticles.length !== 100) {
    throw new Error(`Expected 100 knowledge articles, received ${knowledgeArticles.length}`);
  }

  knowledgeArticles.forEach((article, index) => {
    const expectedNumber = index + 1;

    if (article.number !== expectedNumber) {
      throw new Error(`Knowledge article #${expectedNumber} is numbered ${article.number}`);
    }

    if (!categoryIds.has(article.categoryId)) {
      throw new Error(`Knowledge article #${article.number} uses unknown category "${article.categoryId}"`);
    }

    if (seenSlugs.has(article.slug)) {
      throw new Error(`Duplicate knowledge article slug "${article.slug}"`);
    }
    seenSlugs.add(article.slug);

    if (seenPaths.has(article.path)) {
      throw new Error(`Duplicate knowledge article path "${article.path}"`);
    }
    seenPaths.add(article.path);

    for (const field of ["title", "excerpt", "directAnswer", "neriva"]) {
      if (!article[field]) {
        throw new Error(`Knowledge article #${article.number} is missing ${field}`);
      }
    }

    if (!Array.isArray(article.why) || article.why.length < 3) {
      throw new Error(`Knowledge article #${article.number} needs at least 3 why paragraphs`);
    }

    if (!Array.isArray(article.plan) || article.plan.length < 4) {
      throw new Error(`Knowledge article #${article.number} needs at least 4 plan steps`);
    }

    if (!Array.isArray(article.mistakes) || article.mistakes.length < 3) {
      throw new Error(`Knowledge article #${article.number} needs at least 3 mistakes`);
    }

    if (!Array.isArray(article.faq) || article.faq.length !== 5) {
      throw new Error(`Knowledge article #${article.number} needs exactly 5 FAQ items`);
    }
  });
}

validateKnowledgeArticles();

export function articleBySlug(slug) {
  return knowledgeArticles.find((article) => article.slug === slug);
}

export function relatedArticlesFor(article) {
  const sameCategory = knowledgeArticles.filter((item) => item.categoryId === article.categoryId && item.slug !== article.slug);
  const others = knowledgeArticles.filter((item) => item.categoryId !== article.categoryId);
  return [...sameCategory, ...others].slice(0, 3);
}

export function knowledgeSitemapUrls() {
  return [knowledgeHubPath, ...knowledgeArticles.map((article) => article.path)];
}
